record.field:
[
    {
        "when": "WhatsApp prospect asks for financing and wants follow-up call",
        "call": {
            "name": "create_lead",
            "arguments": {
                "name": "Interesado en Yamaha FZ - financiacion",
                "contact_name": "Martin",
                "description": "Cliente quiere financiacion para Yamaha FZ y pide avanzar hoy.",
                "intent_signal": "Pidio avanzar con propuesta de financiacion",
                "lead_temperature": "hot",
                "sentiment_summary": "Motivado, listo para avanzar",
                "next_action": "Enviar propuesta y llamar en el dia"
            }
        }
    },
    {
        "when": "Telegram user only asks general info and no follow-up intent",
        "call": "Do not call create_lead yet"
    }
]

{
    "name": "create_lead",
    "description": "Create or update a qualified lead/opportunity in CRM",
    "parameters": {
        "type": "object",
        "properties": {
            "name": {
                "type": "string",
                "description": "Lead title or opportunity name"
            },
            "contact_name": {
                "type": "string",
                "description": "Contact person name"
            },
            "email": {
                "type": "string",
                "description": "Email address"
            },
            "phone": {
                "type": "string",
                "description": "Phone number (optional if channel metadata already provides contact)"
            },
            "description": {
                "type": "string",
                "description": "Conversation summary and customer need"
            },
            "intent_signal": {
                "type": "string",
                "description": "Short reason why this is commercially qualified"
            },
            "lead_temperature": {
                "type": "string",
                "description": "Lead temperature: cold, warm, or hot"
            },
            "sentiment_summary": {
                "type": "string",
                "description": "Short customer sentiment summary"
            },
            "preferred_contact_time": {
                "type": "string",
                "description": "Best time window to contact the customer"
            },
            "next_action": {
                "type": "string",
                "description": "Next commercial action agreed with customer"
            }
        },
        "required": ["name"]
    }
}
